package io.mavsdk.kotlin.plugins.log_files

import io.mavsdk.kotlin.System
import kotlin.coroutines.resume
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.suspendCancellableCoroutine

/**
 * Allow to download log files from the vehicle after a flight is complete. For log streaming during
 * flight check the logging plugin.
 */
class LogFiles internal constructor(private val native: LogFilesNative) : AutoCloseable {
    private var closed = false

    /** Possible results returned for calibration commands */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** Progress update */
        NEXT(2),
        /** No log files found */
        NO_LOGFILES(3),
        /** A timeout happened */
        TIMEOUT(4),
        /** Invalid argument */
        INVALID_ARGUMENT(5),
        /** File open failed */
        FILE_OPEN_FAILED(6),
        /** No system is connected */
        NO_SYSTEM(7);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * Progress data coming when downloading a log file.
     *
     * @property progress Progress from 0 to 1
     */
    data class ProgressData(val progress: Float)

    /**
     * Log file entry type.
     *
     * @property id ID of the log file, to specify a file to be downloaded
     * @property date Date of the log file in UTC in ISO 8601 format "yyyy-mm-ddThh:mm:ssZ"
     * @property sizeBytes Size of file in bytes
     */
    data class Entry(val id: Int, val date: String, val sizeBytes: Int)

    /**
     * Get List of log files.
     *
     * @return List of entries
     */
    suspend fun getEntries(): kotlin.Result<List<Entry>> =
        suspendCancellableCoroutine { continuation ->
            val callbackGuard = LogFilesCallbackGuard()
            native.getEntriesAsync() { result, value ->
                val parsedResult = Result.fromValue(result)
                if (continuation.isActive && callbackGuard.tryClaim()) {
                    if (parsedResult == Result.SUCCESS) {
                        continuation.resume(kotlin.Result.success(value))
                    } else {
                        continuation.resume(
                            kotlin.Result.failure(
                                LogFilesException(
                                    parsedResult,
                                    "getEntries failed: ${parsedResult.name}",
                                )
                            )
                        )
                    }
                }
            }
        }

    /**
     * Download log file.
     *
     * @param entry Entry of the log file to download.
     * @param path Path of where to download log file to.
     * @return Progress if result is progress
     */
    fun downloadLogFile(entry: Entry, path: String): Flow<kotlin.Result<ProgressData>> =
        callbackFlow {
            native.downloadLogFileAsync(entry, path) { result, value ->
                val parsedResult = Result.fromValue(result)
                when {
                    parsedResult == Result.NEXT -> trySend(kotlin.Result.success(value))
                    parsedResult == Result.SUCCESS -> close()
                    else -> {
                        trySend(
                            kotlin.Result.failure(
                                LogFilesException(
                                    parsedResult,
                                    "downloadLogFile failed: ${parsedResult.name}",
                                )
                            )
                        )
                        close()
                    }
                }
            }
            awaitClose {}
        }

    /**
     * Erase all log files.
     *
     * @return The result of the request.
     */
    fun eraseAllLogFiles(): Result = Result.fromValue(native.eraseAllLogFiles())

    override fun close() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class LogFilesException(val result: Result, message: String) : Exception(message)

    companion object {
        fun create(system: System): LogFiles =
            LogFiles(createLogFilesNative(system.getHandle())).also { system.registerPlugin(it) }
    }
}

internal interface LogFilesNative {
    fun getEntriesAsync(callback: (Int, List<LogFiles.Entry>) -> Unit)

    fun downloadLogFileAsync(
        entry: LogFiles.Entry,
        path: String,
        callback: (Int, LogFiles.ProgressData) -> Unit,
    )

    fun eraseAllLogFiles(): Int

    fun destroy()
}

internal expect fun createLogFilesNative(systemHandle: Long): LogFilesNative

internal expect class LogFilesCallbackGuard() {
    fun tryClaim(): Boolean
}
